  let user=store.get('SELECT * FROM users WHERE device_hash=?',digest(device));if(!user){user={id:uid(),name:'',contact:''};store.run('INSERT INTO users(id,device_hash,created) VALUES(?,?,?)',user.id,digest(device),store.now())}
  const deviceUserId=user.id;let s=store.get('SELECT * FROM sessions WHERE id=? AND expires>?',digest(cookies.training_session||''),store.now());let binding=s?store.get('SELECT * FROM instructor_sessions WHERE session_id=?',s.id):null;if(s&&options.hosting?.sessionAllowed&&!options.hosting.sessionAllowed(store.get('SELECT contact FROM users WHERE id=?',s.user_id)?.contact,s.created)){store.run('DELETE FROM sessions WHERE id=?',s.id);s=null;}if(s&&(s.ip!==ip||store.get('SELECT device_hash FROM session_devices WHERE session_id=?',s.id)?.device_hash!==digest(device)))s=null;
