 function rate(key,max=20,period=900000){let row=limits.get(key);if(!row||row.end<Date.now()){row={count:0,end:Date.now()+period};limits.set(key,row)}if(++row.count>max)fail(429,'Too many requests; try later');if(limits.size>10000)for(const [k,v]of limits)if(v.end<Date.now())limits.delete(k)}
 function rememberCourse(s,id){if(id)store.run('INSERT OR IGNORE INTO course_visits VALUES(?,?)',s.user_id,id)}
