 function authorize(s,requestedCourse,businessId){let c=courseFor(s);if(requestedCourse&&requestedCourse!==c.id)fail(409,'Course changed in another tab; reload before continuing');if(!canRead(s,c))fail(403,'Access approval required');c=business.resolve(c,s,businessId||business.defaultId(c));if(!c.published&&!s.admin)fail(409,'Business version has no published revision');return c}
 const material=c=>business.read(c,c.published);
 function knownVersion(c,v){return business.known(c,v)}
