 function readableQuestion(c,s,q){if(!q||!discussions.can(q,s.user_id,teacher(s,c))||(!c.businessAdmin&&!store.get('SELECT root_id FROM public_discussion_threads WHERE root_id=?',q.root_id||q.id)))fail(404,'Question not found')}
 function historicalQuestion(c,id){const scope=business.sqlScope(c);return store.get('SELECT id FROM questions WHERE course_id=? AND page_id=? AND '+scope.sql+' LIMIT 1',c.id,id,...scope.args)}
 function ownNote(c,s,id){const scope=business.sqlScope(c);return store.get('SELECT body,updated,material_version FROM notes WHERE user_id=? AND course_id=? AND page_id=? AND '+scope.sql,s.user_id,c.id,id,...scope.args)}
 function questionPageFor(c,id){if(id===business.generalPage(c)||historicalQuestion(c,id))return;return pageFor(c,id)}
 function getMaterial(c,requested,s=null){c=business.resolve(c,s||{admin:true},c.businessId||'v1');const privateVersions=store.setting('privateVersions:'+c.id,[]);const version=Number(requested||((c.businessAdmin||!privateVersions.includes(c.businessDraft))?c.businessDraft:c.published));if(version)revisions.available(c,version);if(!c.businessAdmin&&privateVersions.includes(version))fail(403,'Administrator-only material revision');return {course:c.id,businessVersion:c.businessId,businessVersions:business.list(c,c.businessAdmin),published:c.published,draft:c.draft,version,material:version?business.read(c,version):{lessons:[]},versions:business.history(c,true).filter(v=>c.businessAdmin||!privateVersions.includes(v.version))}}

 function saveMaterial(c,body,s,fromMarkdown=false){if(!fromMarkdown&&(body.material?.source?.format==='pamm-three-lessons-md'||store.get('SELECT version FROM material_sources WHERE course_id=? AND version=?',c.id,c.businessDraft||c.draft)))fail(409,'Update this material by uploading its Markdown source');validateMaterial(body.material,{requireOutcomes:!fromMarkdown});const ids=new Set(body.material.lessons.flatMap(l=>l.pages).map(p=>p.id));for(const row of business.history(c))if(business.read(c,row.version).lessons.flatMap(l=>l.pages).some(p=>!ids.has(p.id)))fail(409,'Keep all previously published page IDs to preserve learning discussions');if(body.baseVersion!==c.draft)fail(409,'Material changed; reload before saving');const next=c.draft+1;store.transaction(()=>{store.run('INSERT INTO versions VALUES(?,?,?,?,?)',c.id,next,JSON.stringify(body.material),actor(s),store.now());store.run('UPDATE courses SET draft=? WHERE id=?',next,c.id);business.record(c,next,body.material);audit(s,'material.saved',{course:c.id,version:next})});return {version:next}}
