 async function callback(req,res,raw){const cfg=larkSettings(store);const data=verifyCallback(raw,req.headers,cfg);if(data.type==='url_verification')return json(res,200,{challenge:data.challenge});if(data.header?.event_type!=='card.action.trigger')fail(400,'Unsupported callback');const actor=data.event?.operator?.open_id;if(!(cfg.adminOpenIds||[]).includes(actor))fail(403,'Lark operator not authorized');const eventId=data.header?.event_id;if(!eventId)fail(400,'Event ID required');if(store.get('SELECT id FROM callbacks WHERE id=?',eventId))return json(res,200,{toast:{type:'info',content:'Already processed / 已处理'}});const value=data.event?.action?.value||{};let result={toast:{type:'success',content:'Done / 已完成'}};
 store.transaction(()=>{if(value.action==='approve')decide(value.requestId,'approved','lark:'+actor,168,false);else if(value.action==='deny')decide(value.requestId,'denied','lark:'+actor);else if(['range','pick_from','pick_to'].includes(value.action)){if(value.action!=='range'){const range=store.setting('card-range:'+actor,{from:dayKey(),to:dayKey()});const date=data.event.action.selected_date;if(!/^\d{4}-\d{2}-\d{2}$/.test(date||''))fail(400,'Select a valid date');range[value.action==='pick_from'?'from':'to']=date;if(range.from>range.to){if(value.action==='pick_from')range.to=range.from;else range.from=range.to}value.from=range.from;value.to=range.to;store.set('card-range:'+actor,range)}dateRange(value.from,value.to);result.card={type:'raw',data:buildCard(store,origin,{from:value.from,to:value.to,history:true})}}else fail(400,'Unknown card action');store.run('INSERT INTO callbacks VALUES(?,?)',eventId,store.now())});json(res,200,result);if(['approve','deny'].includes(value.action))queueMicrotask(()=>lark.sync(true).catch(()=>{}))}
