   if(p==='/api/ppt-public'||p==='/api/ppt-public/extend'||p==='/api/ppt-public/request'||p==='/api/ppt-public/events'){const ip=clientIp(req,trustProxy);try{ppt.throttle(ip)}catch(e){ppt.limited(String(req.headers.authorization||'').replace(/^Bearer /,''),ip,req.headers['x-ppt-visitor']);throw e}res.setHeader('referrer-policy','no-referrer');const bearer=String(req.headers.authorization||'').replace(/^Bearer /,'');if(p==='/api/ppt-public'&&req.method==='GET')return json(res,200,{...ppt.read(bearer,ip,req.headers['x-ppt-visitor'],url.searchParams.get('check')==='1'),...languageForIp(ip,options.countryLookup)});if((p==='/api/ppt-public/extend'||p==='/api/ppt-public/request'||p==='/api/ppt-public/events')&&req.method==='POST'){if(req.headers.origin!==origin||!String(req.headers['content-type']||'').startsWith('application/json'))fail(403,'Cross-origin request refused');const chunks=[];let size=0;for await(const chunk of req){size+=chunk.length;if(size>2048)fail(413,'Request too large');chunks.push(chunk)}let body;try{body=JSON.parse(Buffer.concat(chunks).toString())}catch{fail(400,'Invalid JSON')}return json(res,200,p==='/api/ppt-public/events'?ppt.readingEvent(bearer,ip,req.headers['x-ppt-visitor'],body):p==='/api/ppt-public/request'?ppt.requestAccess(bearer,ip,req.headers['x-ppt-visitor'],body):ppt.extend(bearer,ip,body,req.headers['x-ppt-visitor']))}fail(405,'Method not allowed')}
   if(p.startsWith('/api/public-presentations/')){res.setHeader('x-robots-tag','noindex, nofollow');if(req.method!=='GET')fail(405,'Read-only presentation');rate('public-ppt:'+clientIp(req,trustProxy),120,60000);const id=p.slice('/api/public-presentations/'.length);if(!/^[a-f0-9-]{36}$/.test(id))fail(404,'Public presentation unavailable');return json(res,200,publicPpt.read(id))}
   if(/^\/p\/[a-f0-9-]{36}$/.test(p)){if(req.method!=='GET'&&req.method!=='HEAD')fail(405,'Read-only presentation');res.writeHead(200,{'content-type':'text/html;charset=utf-8','cache-control':'no-store','x-robots-tag':'noindex, nofollow'});return res.end(req.method==='HEAD'?undefined:fs.readFileSync(path.join(root,'public/public-presentation.html')))}
   if(p==='/health')return json(res,200,{ok:true,service:'teach-in-public'});
   if(p.startsWith('/api/agent/')){rate('agent:'+clientIp(req,trustProxy),100,60000);let body={};if(req.method==='POST'){try{body=JSON.parse(await rawBody(req))}catch(e){if(e.status)throw e;fail(400,'Invalid JSON')}}const result=feedbackRoutes.agentRoute(req,p,req.method,body,url.searchParams);return json(res,result.status||200,result.data)}
